+func TestShapeIndexEncodeDecodeZeroEdgeAndMixedChains(t *testing.T) {
+	idx := NewShapeIndex()
+
+	emptyPV := PointVector{}
+	emptyPoly := Polyline{}
+	onePtPoly := Polyline(parsePoints("1:1"))
+	emptyLaxPoly := LaxPolylineFromPoints(nil)
+	onePtLaxPoly := LaxPolylineFromPoints(parsePoints("2:2"))
+	emptyLoop := EmptyLoop()
+	fullLoop := FullLoop()
+	emptyLaxLoop := &LaxLoop{}
+	emptyPolygon := PolygonFromLoops(nil)
+	fullPolygon := FullPolygon()
+	emptyLaxPolygon := LaxPolygonFromPoints(nil)
+	fullLaxPolygon := LaxPolygonFromPoints([][]Point{{}})
+	multiChainPV := PointVector(parsePoints("0:0, 1:1, 2:2, 3:3, 4:4"))
+	multiChainLaxPoly := LaxPolygonFromPoints([][]Point{
+		{},
+		parsePoints("0:0"),
+		parsePoints("1:1, 2:2"),
+		parsePoints("10:10, 10:20, 20:20, 20:10"),
+	})
+
+	ids := []int32{
+		idx.Add(&emptyPV),
+		idx.Add(&emptyPoly),
+		idx.Add(&onePtPoly),
+		idx.Add(emptyLaxPoly),
+		idx.Add(onePtLaxPoly),
+		idx.Add(emptyLoop),
+		idx.Add(fullLoop),
+		idx.Add(emptyLaxLoop),
+		idx.Add(emptyPolygon),
+		idx.Add(fullPolygon),
+		idx.Add(emptyLaxPolygon),
+		idx.Add(fullLaxPolygon),
+		idx.Add(&multiChainPV),
+		idx.Add(multiChainLaxPoly),
+	}
+
+	var buf bytes.Buffer
+	if err := idx.Encode(&buf); err != nil {
+		t.Fatalf("Encode() error = %v", err)
+	}
+
+	var decoded ShapeIndex
+	if err := decoded.Decode(&buf); err != nil {
+		t.Fatalf("Decode() error = %v", err)
+	}
+
+	if decoded.Len() != idx.Len() {
+		t.Fatalf("decoded.Len() = %d, want %d", decoded.Len(), idx.Len())
+	}
+	for _, id := range ids {
+		assertShapesEqual(t, decoded.Shape(id), idx.Shape(id))
+	}
+	quadraticValidate(t, &decoded)
+	testIteratorMethods(t, &decoded)
+}
